UPDATE intake_entries SET slot_template_id = :slot_template_id, slot_position = :slot_position, name = :name, servings = :servings, eaten_at = :eaten_at, day = :day, kcal = :kcal, protein_g = :protein_g, carbs_g = :carbs_g, fat_g = :fat_g, fiber_g = :fiber_g, kcal_low = :kcal_low, kcal_high = :kcal_high, provenance = :provenance, source = :source, portion_note = :portion_note, updated_at = :updated_at, amount_estimated = :amount_estimated, servings_low = :servings_low, servings_high = :servings_high WHERE user_id = :user_id AND id = :id RETURNING user_id, id, client_id, food_id, source_food_id, servings, eaten_at, day,
  kcal, protein_g, carbs_g, fat_g, fiber_g, kcal_low, kcal_high, provenance,
  source, portion_note, created_at, updated_at, name, slot_template_id,
  slot_position, amount_estimated, servings_low, servings_high;
